import re

def semver_compare(a, b):
    # Validate version strings
    def validate(v):
        # Regex for valid semver 2.0.0
        pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
        if not re.match(pattern, v):
            raise ValueError(f"Invalid version string: {v}")
        return v

    try:
        validate(a)
        validate(b)
    except ValueError:
        raise

    # Parse version
    def parse(v):
        # Split into core, pre-release, build
        # Core: MAJOR.MINOR.PATCH
        core_match = re.match(r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)', v)
        if not core_match:
            raise ValueError(f"Invalid version string: {v}")
        major = int(core_match.group(1))
        minor = int(core_match.group(2))
        patch = int(core_match.group(3))

        # Pre-release
        pre_release = None
        pre_match = re.match(r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(-.+)?', v)
        if '-' in v[core_match.end():]:
            pre_release_str = v[core_match.end():].lstrip('-')
            pre_release = pre_release_str.split('.')

        # Build metadata (ignored)
        return (major, minor, patch, pre_release)

    pa = parse(a)
    pb = parse(b)

    # Compare MAJOR, MINOR, PATCH
    for x, y in zip(pa[:3], pb[:3]):
        if x < y:
            return -1
        if x > y:
            return 1

    # Compare pre-release
    # A version with a pre-release is lower than the same version without one
    if pa[3] is None and pb[3] is not None:
        return 1
    if pa[3] is not None and pb[3] is None:
        return -1

    if pa[3] is not None and pb[3] is not None:
        # Compare identifier by identifier
        for x, y in zip(pa[3], pb[3]):
            # Determine if identifiers are all digits
            x_is_digit = x.isdigit()
            y_is_digit = y.isdigit()

            # Two all-digit identifiers numerically
            if x_is_digit and y_is_digit:
                xi = int(x)
                yi = int(y)
                if xi < yi:
                    return -1
                if xi > yi:
                    return 1
            # Two others in ASCII order
            elif not x_is_digit and not y_is_digit:
                if x < y:
                    return -1
                if x > y:
                    return 1
            # An all-digit identifier is lower than any other
            else:
                if x_is_digit:  # x is all-digit, y is not
                    return -1
                else:  # y is all-digit, x is not
                    return 1

        # If every shared identifier is equal, the one with more identifiers is higher
        if len(pa[3]) < len(pb[3]):
            return -1
        elif len(pa[3]) > len(pb[3]):
            return 1

    return 0

